import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { adminProviderListQuerySchema } from '@curenear/shared';
import { createPersistence, createPrismaClient } from '@curenear/db';
import { createAdminDirectoryService } from '@/server/services/admin-directory-service';

/**
 * Performance check for the directory at 100,000 providers.
 *
 * The data is generated by `scripts/seed-provider-directory.ts` (synthetic rows
 * marked `TEST-SYN-`, never production data):
 *
 *   pnpm seed:synthetic-providers -- --count=100000
 *   RUN_DIRECTORY_PERF=1 pnpm --filter @curenear/web test:int -- directory-performance
 *
 * It stays skipped by default so the everyday integration run does not need a
 * six-figure dataset on every machine.
 */
const databaseUrl = process.env.TEST_DATABASE_URL ?? process.env.DATABASE_URL;
const enabled = Boolean(databaseUrl) && process.env.RUN_DIRECTORY_PERF === '1';
const TARGET_MS = 300;
const REQUIRED_ROWS = 100_000;

describe.skipIf(!enabled)('provider directory performance (100k synthetic providers)', () => {
  let prisma: ReturnType<typeof createPrismaClient>;
  let service: ReturnType<typeof createAdminDirectoryService>;
  let syntheticRows = 0;

  beforeAll(async () => {
    prisma = createPrismaClient(databaseUrl as string);
    const persistence = createPersistence(prisma);
    service = createAdminDirectoryService({
      ...persistence,
      now: () => new Date(),
      newId: () => randomUUID(),
    });
    syntheticRows = await prisma.providerOrganization.count({
      where: { registrationNumber: { startsWith: 'TEST-SYN-' }, deletedAt: null },
    });
  });

  afterAll(async () => {
    await prisma.$disconnect();
  });

  async function measure(input: Record<string, unknown>, runs = 7): Promise<number> {
    const query = adminProviderListQuerySchema.parse({ pageSize: 25, ...input });
    // One warm-up run so the planner and page cache are ready.
    await service.list({ userId: randomUUID(), role: 'ADMIN' }, query);
    const samples: number[] = [];
    for (let run = 0; run < runs; run += 1) {
      const started = process.hrtime.bigint();
      await service.list({ userId: randomUUID(), role: 'ADMIN' }, query);
      samples.push(Number(process.hrtime.bigint() - started) / 1e6);
    }
    samples.sort((a, b) => a - b);
    return samples[Math.floor(samples.length / 2)] as number;
  }

  it('has the synthetic dataset', () => {
    expect(syntheticRows).toBeGreaterThanOrEqual(REQUIRED_ROWS);
  });

  it('serves the unfiltered first page under the target', async () => {
    const median = await measure({});
    expect(median).toBeLessThan(TARGET_MS);
  });

  it('serves a combined filtered page under the target', async () => {
    const median = await measure({
      providerType: ['pharmacy', 'clinic'],
      status: ['SUBMITTED', 'UNDER_REVIEW'],
      pin: ['70', '11'],
      licenceExpiringDays: 90,
    });
    expect(median).toBeLessThan(TARGET_MS);
  });

  it('serves the missing-documents filter under the target', async () => {
    const median = await measure({ missingDocuments: true });
    expect(median).toBeLessThan(TARGET_MS);
  });

  it('serves the text search under the target', async () => {
    const median = await measure({ q: '000123' });
    expect(median).toBeLessThan(TARGET_MS);
  });
});
